     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/raceId> "903" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/q3> "0:01:54" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/number> ?number .
