SELECT ?q1 WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/forename> "Bruno" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> "Senna" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/driverId> ?driverId .
  ?q a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/driverId> ?driverId ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/raceId> "354"^^<http://www.w3.org/2001/XMLSchema#integer> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/q1> ?q1 .
}

SELECT ?url WHERE {
  ?cr a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/ConstructorResults> ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/ConstructorResults/raceId> "9"^^<http://www.w3.org/2001/XMLSchema#integer> ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/ConstructorResults/constructorId> ?constructorId ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/ConstructorResults/points> ?points .
  {
    SELECT (MAX(?p) AS ?maxPoints) WHERE {
      ?cr2 a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/ConstructorResults> ;
           <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/ConstructorResults/raceId> "9"^^<http://www.w3.org/2001/XMLSchema#integer> ;
           <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/ConstructorResults/points> ?p .
    }
  }
  FILTER(xsd:decimal(?points) = ?maxPoints)
  ?c a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Constructors> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Constructors/constructorId> ?constructorId ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Constructors/url> ?url .
}

SELECT ?url WHERE {
  ?lt a <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/LapTime> ;
      <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/LapTime/raceid> "161" ;
      <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/LapTime/time> "1:27" ;
      <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/LapTime/driverid> ?driverid .
  ?d a <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Driver/driverid> ?driverid ;
     <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Driver/url> ?url .
}

SELECT ?driverRef WHERE {
  ?q a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/raceId> "20" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/q2> ?q2 ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/hasDrivers> ?d .
  ?d <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/driverRef> ?driverRef .
  FILTER(?q2 = "" || ?q2 = "\\N")
}

SELECT (COUNT(?r) AS ?n) WHERE {
  ?race a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> "Bahrain Grand Prix" ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/year> ?year .
  FILTER(?year = "2007")

  ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/hasRaces> ?race ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/hasStatus> ?status .

  ?status <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Status/status> ?statusName .

  FILTER(?statusName != "Finished")
}

SELECT ?forename ?surname ?dob WHERE {
  ?r a <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Results> ;
     <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Results/raceid> "592" ;
     <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Results/hasStatus> ?st ;
     <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Results/hasDrivers> ?d .
  ?st <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Status/status> "Finished" .
  ?d <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
     <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Driver/surname> ?surname ;
     <http://bird-bird_formula_1-ontology-20260805-004009/ontology/vkg-bird_formula_1/Driver/dob> ?dob .
}
ORDER BY ?dob
LIMIT 1

SELECT ?surname WHERE {
  ?q a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/raceId> 19 ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/q2> ?q2 ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Qualifying/hasDrivers> ?d .
  ?d <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
  FILTER (?q2 != "")
}
ORDER BY ?q2
LIMIT 1

SELECT ?name WHERE {
  {
    SELECT (MIN(?ym2) AS ?minym) WHERE {
      ?r2 a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/date> ?d2 .
      BIND(SUBSTR(STR(?d2),1,7) AS ?ym2)
    }
  }
  ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> ?name ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/date> ?date .
  BIND(SUBSTR(STR(?date),1,7) AS ?ym)
  FILTER(?ym = ?minym)
}

SELECT ?forename ?surname (SUM(?points) AS ?total)
WHERE {
  ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/driverId> ?did ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/points> ?points .
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/driverId> ?did ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
}
GROUP BY ?forename ?surname
ORDER BY DESC(?total)
LIMIT 1

SELECT (AVG(?ms) AS ?avgLapTimeMs) WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/forename> "Lewis" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> "Hamilton" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/driverId> ?driverId .

  ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> "Malaysian Grand Prix" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/year> ?year ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/raceId> ?raceId .
  FILTER(xsd:integer(?year) = 2009)

  ?lt a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime> ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime/driverId> ?driverId ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime/raceId> ?raceId ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime/milliseconds> ?ms .
}

SELECT (SUM(?notFirst) * 100.0 / COUNT(?r) AS ?pct)
WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> "Hamilton" .
  ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/hasDrivers> ?d ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/hasRaces> ?race .
  OPTIONAL { ?r <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/position> ?pos }
  ?race a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/year> ?y .
  FILTER(xsd:integer(?y) >= 2010)
  BIND(IF(BOUND(?pos) && xsd:integer(?pos) = 1, 0, 1) AS ?notFirst)
}

SELECT ?fn ?sn ?nat ?wins (MAX(?pts) AS ?maxPoints)
WHERE {
  {
    SELECT ?did (COUNT(?r) AS ?wins)
    WHERE {
      ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
         <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/driverId> ?did ;
         <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/positionOrder> ?po .
      FILTER(?po = 1)
    }
    GROUP BY ?did
    ORDER BY DESC(?wins)
    LIMIT 1
  }
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/driverId> ?did ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/forename> ?fn ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> ?sn ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/nationality> ?nat .
  ?r2 a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/driverId> ?did ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/points> ?pts .
}
GROUP BY ?fn ?sn ?nat ?wins

SELECT ?forename ?surname ((YEAR(NOW()) - YEAR(?dob)) AS ?age)
WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/nationality> "Japanese" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/dob> ?dob ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/forename> ?forename ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> ?surname .
}
ORDER BY DESC(?dob)
LIMIT 1

SELECT ?driverId ?laps ?maxLaps (xsd:decimal(?laps) / xsd:decimal(?maxLaps) AS ?completionRate)
WHERE {
  ?race a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/raceId> ?raceId ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/date> ?date .
  FILTER(?date = "1983-07-16"^^xsd:date)

  ?result a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/raceId> ?raceId ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/driverId> ?driverId ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/laps> ?laps .

  {
    SELECT ?raceId (MAX(?laps2) AS ?maxLaps)
    WHERE {
      ?r2 a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/raceId> ?raceId ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/laps> ?laps2 .
    }
    GROUP BY ?raceId
  }
}

SELECT DISTINCT ?raceName WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/forename> "Alex" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> "Yoong" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/driverId> ?driverId .

  ?lt a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime> ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime/driverId> ?driverId ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime/position> ?pos ;
      <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/LapTime/raceId> ?raceId .

  FILTER (xsd:integer(?pos) < 20)

  ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/raceId> ?raceId ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> ?raceName .
}

SELECT ?raceName ?raceDate ?points WHERE {
  ?d a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/forename> "Lewis" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/surname> "Hamilton" ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Driver/driverId> ?driverId .
  ?res a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
       <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/driverId> ?driverId ;
       <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/raceId> ?raceId ;
       <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/points> ?points .
  ?race a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/raceId> ?raceId ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> ?raceName ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/date> ?raceDate .
}
ORDER BY ?raceDate
LIMIT 1

SELECT (MAX(?speed) AS ?fastestLapSpeed) WHERE {
  ?r a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/fastestLapSpeed> ?speed ;
     <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/hasRaces> ?race .
  ?race a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/year> ?year ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> ?name .
  FILTER(?year = 2009)
  FILTER(?name = "Spanish Grand Prix")
  FILTER(?speed != "")
}

SELECT (COUNT(DISTINCT ?driver) AS ?n) WHERE {
  ?race a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> ?raceName ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/year> ?year .
  FILTER(?raceName = "Chinese Grand Prix" && ?year = 2008)

  ?result a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/hasRaces> ?race ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/driverId> ?driver ;
          <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/hasStatus> ?status .

  ?status <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Status/status> ?statusLabel .
  FILTER(?statusLabel = "Finished")
}

SELECT ?driverRef WHERE {
  ?race a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races> ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/name> "Canadian Grand Prix" ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/year> ?year ;
        <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Races/raceId> ?raceId .
  FILTER(xsd:integer(?year) = 2007)

  ?res a <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results> ;
       <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/raceId> ?raceId ;
       <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/positionOrder> ?pos ;
       <http://bird-bird_formula_1-ontology-20260804-132214/ontology/vkg-bird_formula_1/Results/driverId> ?driverId .
  FILTER(xsd:integer(?pos) = 1)

